'use strict';
const fs=require('fs'); const path=require('path'); const crypto=require('crypto'); const cp=require('child_process');
const root=path.resolve(__dirname,'..');
const carrierNames=['SMARTER_JUSTICE__PRE110_DEPLOY_RUNTIME.tgz','SMARTER_JUSTICE__PRE110_DEPLOY_RUNTIME (1).tgz','SMARTER_JUSTICE__PRE110_DEPLOY_RUNTIME(1).tgz'];
const wrapperNames=['SMARTER_JUSTICE__ONE_FILE_GITHUB_UPLOAD__PRE110.zip','SMARTER_JUSTICE__ONE_FILE_GITHUB_UPLOAD__PRE110 (1).zip','SMARTER_JUSTICE__ONE_FILE_GITHUB_UPLOAD__PRE110(1).zip'];
let archive=carrierNames.map(n=>path.join(root,n)).find(fs.existsSync);
const wrapper=wrapperNames.map(n=>path.join(root,n)).find(fs.existsSync);
const extracted=path.join(root,'.runtime','PRE110_DEPLOY_RUNTIME_FROM_UPLOAD.tgz');
function fail(m){console.error(`[PRE110 DEPLOY] ${m}`);process.exit(1)} function assert(x,m){if(!x)fail(m)}
if(!archive&&wrapper){fs.mkdirSync(path.dirname(extracted),{recursive:true});const py=`import zipfile,sys\nz=zipfile.ZipFile(sys.argv[1])\nname='SMARTER_JUSTICE__PRE110_DEPLOY_RUNTIME.tgz'\nassert name in z.namelist(), 'carrier missing from wrapper'\nopen(sys.argv[2],'wb').write(z.read(name))`;const r=cp.spawnSync(process.env.PYTHON_BIN||'python3',['-c',py,wrapper,extracted],{encoding:'utf8'});if(r.status!==0)fail('Could not extract PRE110 runtime from upload ZIP: '+String(r.stderr||r.stdout||''));archive=extracted;}
assert(archive,'Upload SMARTER_JUSTICE__ONE_FILE_GITHUB_UPLOAD__PRE110.zip to the repository root without unzipping it.');
const expectedSha256='a0c7c704dde825eda264a3d6747f749433d67a95b29aa4f881c359673b430f31', expectedBytes=12724334;
const target=path.join(root,'.runtime','pre110-live'); const sha=f=>crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');
const stat=fs.statSync(archive); assert(stat.size===expectedBytes,`carrier size mismatch ${stat.size} != ${expectedBytes}`); const digest=sha(archive); assert(digest===expectedSha256,`carrier SHA mismatch ${digest}`);
const members=cp.execFileSync('tar',['-tzf',archive],{encoding:'utf8',maxBuffer:64*1024*1024}); for(const raw of members.split(/\r?\n/)){const n=raw.trim();if(!n)continue;const q=n.replace(/^\.\//,'');assert(!path.posix.isAbsolute(q),`unsafe archive path ${n}`);assert(!q.split('/').includes('..'),`unsafe parent path ${n}`)}
fs.rmSync(target,{recursive:true,force:true});fs.mkdirSync(target,{recursive:true});cp.execFileSync('tar',['-xzf',archive,'-C',target],{stdio:'inherit'});
