const imm=readJson('data/pre109-immigration-form-library.json'), tax=readJson('data/pre109-tax-form-library.json');assert(imm.counts?.forms===108&&imm.counts?.instructions===92,'Immigration library mismatch');assert(tax.counts?.total===65&&tax.counts?.forms===46&&tax.counts?.instructions===19,'Tax library mismatch');
for(const rel of ['server.js','lib/acquisitionRevenuePre110.js','lib/formEnginePre109.js','public/owner-acquisition-revenue.html','public/pre110-owner-acquisition.js','public/forms-center.html','coordination/pre110/SHARED_CAPABILITY_DISPOSITION_MATRIX__PRE110.json','governance/current/ROGER_RULE_DGO_V0.6_UEC1.4_SHARED_REVENUE_COORDINATION__PRE110.md','scripts/pre109_fill_official_pdf.py','vendor/pre109/immigration-oasis/data/official-pdf-cache/g-1145.pdf','vendor/pre109/justice-tax-solutions/assets/official-forms/irs-individual-income-tax/f1040 U.S. Individual Income Tax Return.pdf','vendor/pre109/justice-tax-solutions/assets/official-forms/irs-tax-debt-resolution/f9465 Installment Agreement Request.pdf','.python-vendor/pypdf/__init__.py'])assert(exists(rel),`missing deploy-critical file ${rel}`);
for(const rel of ['server.js','lib/acquisitionRevenuePre110.js','lib/formEnginePre109.js','public/pre110-owner-acquisition.js'])cp.execFileSync(process.execPath,['--check',path.join(target,rel)],{stdio:'inherit'});
const pyEnv={...process.env,PYTHONPATH:path.join(target,'.python-vendor')+(process.env.PYTHONPATH?path.delimiter+process.env.PYTHONPATH:'')};cp.execFileSync(process.env.PYTHON_BIN||'python3',['-c','import pypdf; print(pypdf.__version__)'],{stdio:'inherit',env:pyEnv});
