const marker={schemaVersion:'smarter-justice.pre110.render-bootstrap.v1',release:'v2.0.0-pre110',carrier:wrapper?path.basename(wrapper):path.basename(archive),carrierSha256:digest,carrierBytes:stat.size,dgo:'0.6.0',coordinationStandard:'UEC-1.4',qualification:receipt.qualification,preservedLibraries:{immigration:imm.counts,tax:tax.counts},productionAuthorization:false,preparedAt:new Date().toISOString()};fs.writeFileSync(path.join(target,'.pre110-render-bootstrap.json'),JSON.stringify(marker,null,2)+'\n');console.log(`[PRE110 DEPLOY] verified ${marker.release}; DGO=${marker.dgo}/${marker.coordinationStandard}; carrier=${digest}`);
